import { network } from "hardhat";

async function main() {
  const { ethers } = await network.connect({ network: "robinhoodMainnet" });
  const abiCoder = ethers.AbiCoder.defaultAbiCoder();

  const poolKeyType = "tuple(address currency0, address currency1, uint24 fee, int24 tickSpacing, address hooks)";
  const swapParamsType = `tuple(${poolKeyType} poolKey, bool zeroForOne, uint128 amountIn, uint128 amountOutMinimum, bytes hookData)`;

  function decodeFull(calldata: string, label: string) {
    console.log(`\n========== ${label} ==========`);

    if (calldata.length % 2 !== 0) {
      console.log(`*** ERROR: calldata has ODD length (${calldata.length} chars) -- transcription error, skipping ***`);
      return;
    }

    const withoutSelector = "0x" + calldata.slice(10);
    const [commands, inputs, deadline] = abiCoder.decode(["bytes", "bytes[]", "uint256"], withoutSelector);
    console.log("commands:", commands);
    console.log("deadline:", deadline.toString());

    const inner = inputs[0];
    const [actions, params] = abiCoder.decode(["bytes", "bytes[]"], inner);
    console.log("actions:", actions);
    console.log("num params:", params.length);

    // Decode params[0] as ExactInputSingleParams
    const swapParams = abiCoder.decode([swapParamsType], params[0])[0];
    console.log("\n--- params[0] (ExactInputSingleParams) ---");
    console.log("poolKey.currency0:", swapParams.poolKey.currency0);
    console.log("poolKey.currency1:", swapParams.poolKey.currency1);
    console.log("poolKey.fee:", swapParams.poolKey.fee.toString());
    console.log("poolKey.tickSpacing:", swapParams.poolKey.tickSpacing.toString());
    console.log("poolKey.hooks:", swapParams.poolKey.hooks);
    console.log("zeroForOne:", swapParams.zeroForOne);
    console.log("amountIn:", swapParams.amountIn.toString());
    console.log("amountOutMinimum:", swapParams.amountOutMinimum.toString());
    console.log("hookData:", swapParams.hookData);
    console.log("hookData length:", (swapParams.hookData.length - 2) / 2, "bytes");

    // Decode params[1] and params[2] as (Currency, uint256)
    const [currency1, amount1] = abiCoder.decode(["address", "uint256"], params[1]);
    const [currency2, amount2] = abiCoder.decode(["address", "uint256"], params[2]);
    console.log("\n--- params[1] (SETTLE_ALL) ---");
    console.log("currency:", currency1, "| amount:", amount1.toString());
    console.log("\n--- params[2] (TAKE_ALL) ---");
    console.log("currency:", currency2, "| amount:", amount2.toString());
  }

  // Build OUR calldata by ENCODING it fresh with real values -- not
  // hand-transcribing a huge hex string a second time, which is exactly
  // what just caused an error. This exercises the identical structure
  // our contract builds (commands=0x10, actions=0x06/0x0c/0x0f), with
  // the real NVDA pool key and real amounts from tonight's attempt.
  const poolKey = {
    currency0: "0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168",
    currency1: "0xd0601CE157Db5bdC3162BbaC2a2C8aF5320D9EEC",
    fee: 3000,
    tickSpacing: 60,
    hooks: "0x0000000000000000000000000000000000000000",
  };
  const amountIn = 837900n;
  const amountOutMinimum = 3818928000000000n; // matches earlier trace (0xd961117419bbf)

  const swapParamsEncoded = abiCoder.encode(
    [swapParamsType],
    [{ poolKey, zeroForOne: true, amountIn, amountOutMinimum, hookData: "0x" }]
  );
  const settleParamsEncoded = abiCoder.encode(["address", "uint256"], [poolKey.currency0, amountIn]);
  const takeParamsEncoded = abiCoder.encode(["address", "uint256"], [poolKey.currency1, 0]);

  const actions = "0x060c0f";
  const params = [swapParamsEncoded, settleParamsEncoded, takeParamsEncoded];
  const inner = abiCoder.encode(["bytes", "bytes[]"], [actions, params]);

  const commands = "0x10";
  const inputs = [inner];
  const deadline = Math.floor(Date.now() / 1000) + 3600;

  const executeSelector = "0x3593564c";
  const outerEncoded = abiCoder.encode(["bytes", "bytes[]", "uint256"], [commands, inputs, deadline]);
  const OUR_CALLDATA_FRESH = executeSelector + outerEncoded.slice(2);

  const REAL_CALLDATA =
    "";

  const REAL_CALLDATA_2 =
    "";

  decodeFull(OUR_CALLDATA_FRESH, "OUR TRANSACTION (freshly re-encoded, identical to what the contract builds)");
  decodeFull(REAL_CALLDATA, "REAL SUCCESSFUL TRANSACTION (native ETH swap -- different shape)");
  decodeFull(REAL_CALLDATA_2, "REAL SUCCESSFUL TRANSACTION #2 (checking if token-to-token)");
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
